-- SALY only. Six tax-comparable financing alternatives. Reuse saly.escenarios and existing canonical financial model.
-- No changes to LF, no DDL, no writes to checkpoints; all taxes and unverified rates remain NULL.
BEGIN;
DO $guard$ BEGIN
 IF (SELECT count(*) FROM saly.programas_investigacion p JOIN saly.proyecto pr ON pr.id=p.proyecto_id WHERE p.codigo='SALY_FONDEO_LEGAL' AND pr.codigo='SALY-001') <> 1 THEN
   RAISE EXCEPTION 'BLOCK_SALY_FONDEO_PROJECT_NOT_IDENTIFIED';
 END IF;
 IF EXISTS (SELECT 1 FROM saly.escenarios WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014','SALY-ESC-015','SALY-ESC-016')) THEN
   RAISE EXCEPTION 'BLOCK_SALY_FONDEO_SCENARIOS_ALREADY_REGISTERED';
 END IF;
END $guard$;
