DO $verify$ DECLARE v_n integer; BEGIN
 SELECT count(*) INTO v_n FROM saly.escenarios
 WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014','SALY-ESC-015','SALY-ESC-016')
 AND estado='BORRADOR'
 AND parametros->>'proyecto'='SALY-001'
 AND parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS'
 AND (parametros->'validacion'->>'tributaria')='PENDIENTE'
 AND resultados->>'estado_resultado'='PENDIENTE_VALIDACION_TRIBUTARIA'
 AND (resultados->>'importe_tributos_pen') IS NULL
 AND jsonb_array_length(parametros->'impuestos_a_validar')>=4;
 IF v_n <> 6 THEN RAISE EXCEPTION 'BLOCK_SALY_FONDEO_FISCAL_SCENARIOS_BAD_COUNT %',v_n; END IF;
 IF (SELECT count(*) FROM saly.escenarios WHERE parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS' AND parametros->>'programa'='SALY_FONDEO_LEGAL')<>6 THEN
   RAISE EXCEPTION 'BLOCK_SALY_FONDEO_FISCAL_SCENARIOS_BAD_FAMILY'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.programas_investigacion p ON p.id=u.programa_id
 WHERE p.codigo='SALY_FONDEO_LEGAL' AND c.estado='DONE')<>2
 THEN RAISE EXCEPTION 'BLOCK_SALY_FONDEO_CHECKPOINT_DRIFT'; END IF;
END $verify$;
COMMIT;
